"""Reconcile a vessel's cargo manifest against gate scale telemetry."""

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple


class ManifestError(Exception):
    pass


@dataclass
class Container:
    container_id: str
    bill_of_lading: str
    declared_weight_kg: float
    scale_reading: Optional[str]  # raw telemetry string, None/empty if not yet weighed at the gate


@dataclass
class ManifestReport:
    pending_weigh: List[str] = field(default_factory=list)
    discrepancies: List[Tuple[str, float]] = field(default_factory=list)
    total_declared: float = 0.0
    total_actual: float = 0.0
    total_surcharge: float = 0.0


def reconcile_manifest(
    containers: List[Container],
    rate_schedule: Dict[str, float],
    tolerance_kg: float = 50.0,
) -> ManifestReport:
    """Cross-check declared cargo weights against gate scale readings and
    flag containers that still need to be weighed or whose numbers don't
    line up, so the terminal can chase them down before the vessel sails."""
    report = ManifestReport()

    for container in containers:
        try:
            actual_weight = float(container.scale_reading)
        except (TypeError, ValueError):
            actual_weight = 0.0
            report.pending_weigh.append(container.container_id)
            continue

        try:
            surcharge_rate = rate_schedule[container.bill_of_lading]
        except KeyError:
            raise ManifestError(
                f"no rate schedule entry for bill of lading {container.bill_of_lading}"
            )

        diff = actual_weight - container.declared_weight_kg
        if abs(diff) > tolerance_kg:
            report.discrepancies.append((container.container_id, diff))

        report.total_declared += container.declared_weight_kg
        report.total_actual += actual_weight
        report.total_surcharge += actual_weight * surcharge_rate

    report.discrepancies.sort(key=lambda item: abs(item[1]), reverse=True)
    return report


def summarize(report: ManifestReport) -> str:
    lines = [
        f"declared total: {report.total_declared:.1f} kg",
        f"actual total:   {report.total_actual:.1f} kg",
        f"surcharge:      {report.total_surcharge:.2f}",
    ]
    if report.pending_weigh:
        lines.append(f"awaiting scale: {', '.join(report.pending_weigh)}")
    for container_id, diff in report.discrepancies:
        direction = "over" if diff > 0 else "under"
        lines.append(f"{container_id}: {abs(diff):.1f} kg {direction} declared weight")
    return "\n".join(lines)
